import re
from decimal import Decimal

MAX_AMOUNT_CENTS = 100_000_000  # 1000000.00
_MAX_AMOUNT = Decimal("1000000.00")
_STRING_AMOUNT = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _decimal_to_cents(value):
    # All operations here are exact and independent of the decimal context:
    # is_finite, as_tuple, and comparisons never round, and no arithmetic
    # is performed on Decimal values.
    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = value.as_tuple()
    if not any(digits):
        raise ValueError("amount must be greater than zero")
    if sign:
        raise ValueError("amount must be positive")
    # Drop trailing zeros (they do not change the value) so the exponent
    # reflects the true precision of the value.
    n = len(digits)
    while digits[n - 1] == 0:
        n -= 1
        exp += 1
    if exp < -2:
        raise ValueError("amount is not exactly representable in cents")
    if value > _MAX_AMOUNT:
        raise ValueError("amount must not exceed 1000000.00")
    # Strip leading zeros, then the coefficient is at most 9 digits because
    # the value is bounded and has at most two fractional digits.
    start = 0
    while digits[start] == 0:
        start += 1
    coefficient = int("".join(str(d) for d in digits[start:n]))
    return coefficient * 10 ** (exp + 2)


def parse_amount_cents(value):
    """Validate an amount and return it as an exact integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("amount must not be a bool")
    if isinstance(value, Decimal):
        return _decimal_to_cents(value)
    if isinstance(value, int):
        if value <= 0:
            raise ValueError("amount must be greater than zero")
        if value > 1_000_000:
            raise ValueError("amount must not exceed 1000000.00")
        return value * 100
    if isinstance(value, str):
        if _STRING_AMOUNT.fullmatch(value) is None:
            raise ValueError("amount string must match [+-]?[0-9]+(\\.[0-9]+)?")
        return _decimal_to_cents(Decimal(value))
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def cents_to_amount(cents):
    """Return an exact Decimal with exponent -2 for a non-negative cent count."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(parse_amount_cents(value))


def format_amount(value):
    return format(value, ".2f")
