from .money import (
    MAX_AMOUNT_CENTS,
    cents_to_amount,
    format_amount,
    parse_amount_cents,
)


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    # Each item is validated by the same rules as parse_amount. Totals are
    # summed as integer cents, so the result is exact regardless of the
    # caller's decimal context precision and the input is not modified.
    total_cents = 0
    for item in amounts:
        total_cents += parse_amount_cents(item)
    if total_cents > MAX_AMOUNT_CENTS:
        raise ValueError("total must not exceed 1000000.00")
    return {"total": format_amount(cents_to_amount(total_cents)), "count": len(amounts)}
